def containsAllCodes(s, k):
    need = 1 << k
    if len(s) < need + k - 1:
        return False
    mask = need - 1
    seen = bytearray(need)
    got = 0
    h = 0
    for i, ch in enumerate(s):
        h = ((h << 1) | (ch == '1')) & mask
        if i >= k - 1 and not seen[h]:
            seen[h] = 1
            got += 1
            if got == need:
                return True
    return False
